EXTRN MsgOnly1To20:BYTE
EXTRN StatusKeys:BYTE
EXTRN StatusNames:BYTE
EXTRN WeaponNames:BYTE
EXTRN ArmourNames:BYTE
EXTRN MsgPartyOrganization:BYTE
EXTRN MsgOption:BYTE
EXTRN MsgMenuExamine:BYTE
EXTRN MsgMenuCreate:BYTE
EXTRN MsgMenuForm:BYTE
EXTRN MsgMenuDisperse:BYTE
EXTRN MsgMenuTerminate:BYTE
