EXTRN MsgMenuLook:BYTE
EXTRN OrganizeKeys:BYTE
EXTRN OrganizeMenu:BYTE
EXTRN MsgNoOneThere:BYTE
EXTRN MsgNameColon:BYTE
EXTRN MsgSexColon:BYTE
EXTRN MsgRaceColon:BYTE
