PUBLIC RunOrganizeMenu
;------------------------------------------------------------------------------
; RunOrganizeMenu: the "Party Organization" menu, chosen with AskChoice (key, name,
; Enter); runs the chosen command and shows the menu again, until M, Q or Esc.
; Uses: AX, BX, CX.
;------------------------------------------------------------------------------
RunOrganizeMenu:	pushf	;@14C9
	push dx	;@14CA
	push si	;@14CB
	push di	;@14CC
RunOrganize_Redraw:	call ClearMenu	;@14CD
	mov dx, 1CC0h	;@14D0
	call DrawMenuFrame	;@14D3
	mov dh, 0Bh	;@14D6
	mov dl, 0Bh	;@14D8
	lea si, MsgPartyOrganization	;@14DA
	call PrintAt	;@14DE
	mov dh, 0Dh	;@14E1
	mov dl, 10h	;@14E3
	lea si, MsgOption	;@14E5
	call PrintAt	;@14E9
	mov dh, 0Fh	;@14EC
	mov dl, 0Ah	;@14EE
	lea si, MsgMenuExamine	;@14F0
	call PrintAt	;@14F4
	mov dh, 10h	;@14F7
	mov dl, 0Bh	;@14F9
	lea si, MsgMenuCreate	;@14FB
	call PrintAt	;@14FF
	mov dh, 11h	;@1502
	mov dl, 0Dh	;@1504
	lea si, MsgMenuForm	;@1506
	call PrintAt	;@150A
	mov dh, 12h	;@150D
	mov dl, 0Bh	;@150F
	lea si, MsgMenuDisperse	;@1511
	call PrintAt	;@1515
	mov dh, 13h	;@1518
	mov dl, 0Ah	;@151A
	lea si, MsgMenuTerminate	;@151C
	call PrintAt	;@1520
	mov dh, 14h	;@1523
	mov dl, 0Bh	;@1525
	lea si, MsgMenuLook	;@1527
	call PrintAt	;@152B
	mov dh, 15h	;@152E
	mov dl, 0Fh	;@1530
	lea si, MsgMenuMain	;@1532
	call PrintAt	;@1536
	mov dh, 0Dh	;@1539
	mov dl, 17h	;@153B
	call SwapCursor	;@153D
	mov cx, 9	; 9 keys: E C F D T M Q L Esc	;@1540
	lea di, OrganizeKeys	;@1543
	lea si, OrganizeMenu	;@1547
	call AskChoice	;@154B
	cmp al, 45h	; 'E'	;@154E
	je RunOrganize_Examine	;@1550
	cmp al, 43h	; 'C'	;@1552
	je RunOrganize_Create	;@1554
	cmp al, 46h	; 'F'	;@1556
	je RunOrganize_Form	;@1558
	cmp al, 44h	; 'D'	;@155A
	je RunOrganize_Disperse	;@155C
	cmp al, 54h	; 'T'	;@155E
	je RunOrganize_Terminate	;@1560
	cmp al, 4Ch	; 'L'	;@1562
	je RunOrganize_Look	;@1564
	pop di	;@1566
	pop si	;@1567
	pop dx	;@1568
	popf	;@1569
	ret	;@156A
RunOrganize_Examine:	call ExamineRegister	;@156B
	jmp RunOrganize_Redraw	;@156E
RunOrganize_Create:	call CreateChar	;@1571
	jmp RunOrganize_Redraw	;@1574
RunOrganize_Form:	call FormParty	;@1577
	jmp RunOrganize_Redraw	;@157A
RunOrganize_Disperse:	call DisperseParty	;@157D
	jmp RunOrganize_Redraw	;@1580
RunOrganize_Terminate:	call TerminateChar	;@1583
	jmp RunOrganize_Redraw	;@1586
RunOrganize_Look:	call LookAtChar	;@1589
	jmp RunOrganize_Redraw	;@158C
;------------------------------------------------------------------------------
; LookAtChar: "Look at a Character": ask a roster number (1-20) and show the character:
; name, sex, race, type (class), status, weapon, armour on the left; strength, dexterity,
; intelligence, wisdom, hit points, experience, food and gold on the right. For a member of
; the party the party's copy (PartyChars) is shown, not the roster's. The letters are turned into
; names by finding them in the key strings (a letter not found gives the last name).
; Uses: nothing (saves all).
;------------------------------------------------------------------------------
LookAtChar:	pushf	;@158F
	push ax	;@1590
	push bx	;@1591
	push cx	;@1592
	push dx	;@1593
	push si	;@1594
	push di	;@1595
	push es	;@1596
	mov ax, ds	;@1597
	mov es, ax	;@1599
	call ClearMenu	;@159B
	mov dh, 0Fh	;@159E
	mov dl, 0Ah	;@15A0
	lea si, MsgLookTitle	;@15A2
	call PrintAt	;@15A6
	mov dh, 12h	;@15A9
	mov dl, 10h	;@15AB
	lea si, MsgEntry	;@15AD
	call PrintAt	;@15B1
	call AskNumber	; AskNumber: AL = BCD, AH = binary	;@15B4
	cmp ah, 0	;@15B7
	jne LookAtChar_TestMax	;@15BA
	jmp LookAtChar_BadNum	;@15BC
LookAtChar_TestMax:	cmp ah, 14h	; 20	;@15BF
	jbe LookAtChar_Fetch	;@15C2
	jmp LookAtChar_BadNum	;@15C4
LookAtChar_Fetch:	mov dl, al	;@15C7
	mov bl, ah	;@15C9
	call RosterRecord	; RosterRecord	;@15CB
	cmp byte ptr [bx], 0	; empty slot?	;@15CE
	jne LookAtChar_Show	;@15D1
	jmp LookAtChar_NoOne	;@15D3
LookAtChar_Show:	call ClearMenu	;@15D6
	mov al, dl	;@15D9
	mov dh, 0Bh	;@15DB
	mov dl, 0Fh	;@15DD
	lea si, MsgEntry	; "Entry#" and the number	;@15DF
	call PrintAt	;@15E3
	call PrintBcdByte	;@15E6
	cmp byte ptr [bx+10h], 0FFh	; in the party?	;@15E9
	jne LookAtChar_Fields	;@15ED
	mov cx, 4	; find the roster number among the members ...	;@15EF
	mov bx, cx	;@15F2
	lea di, PartyRosterNums	;@15F4
	mov al, ah	;@15F8
	repne scasb	;@15FA
	sub bl, cl	;@15FC
	dec bl	; ... BL = its place (0-3)	;@15FE
	mov al, 40h	;@1600
	mul bl	;@1602
	mov bx, ax	;@1604
	lea bx, PartyChars[bx]	; the party's record	;@1606
LookAtChar_Fields:	mov dh, 0Dh	;@160A
	mov dl, 3	;@160C
	lea si, MsgNameColon	;@160E
	call PrintAt	;@1612
	lea si, [bx]	; +00 name	;@1615
	call PrintStr	;@1617
	mov dh, 0Eh	;@161A
	mov dl, 3	;@161C
	lea si, MsgSexColon	;@161E
	call PrintAt	;@1622
	mov al, byte ptr [bx+18h]	; sex	;@1625
	lea di, SexKeys	;@1628
	mov cx, 3	;@162C
	mov si, cx	;@162F
	repne scasb	;@1631
	sub si, cx	;@1633
	dec si	;@1635
	shl si, 1	;@1636
	mov si, word ptr SexNames[si]	;@1638
	call PrintStr	;@163C
	mov dh, 0Fh	;@163F
	mov dl, 3	;@1641
	lea si, MsgRaceColon	;@1643
	call PrintAt	;@1647
	mov al, byte ptr [bx+16h]	; race	;@164A
	lea di, RaceKeys	;@164D
	mov cx, 5	;@1651
	mov si, cx	;@1654
	repne scasb	;@1656
	sub si, cx	;@1658
	dec si	;@165A
	shl si, 1	;@165B
	mov si, word ptr RaceNames[si]	;@165D
	call PrintStr	;@1661
	mov dh, 10h	;@1664
	mov dl, 3	;@1666
	lea si, MsgTypeColon	;@1668
	call PrintAt	;@166C
	mov al, byte ptr [bx+17h]	; class	;@166F
	lea di, ClassKeys	;@1672
	mov cx, 0Bh	;@1676
	mov si, cx	;@1679
	repne scasb	;@167B
	sub si, cx	;@167D
	dec si	;@167F
	shl si, 1	;@1680
	mov si, word ptr ClassNames[si]	;@1682
	call PrintStr	;@1686
	mov dh, 11h	;@1689
	mov dl, 1	;@168B
	lea si, MsgStatusColon	;@168D
	call PrintAt	;@1691
	mov al, byte ptr [bx+11h]	; status	;@1694
	lea di, StatusKeys	;@1697
	mov cx, 4	;@169B
	mov si, cx	;@169E
	repne scasb	;@16A0
	sub si, cx	;@16A2
	dec si	;@16A4
	shl si, 1	;@16A5
	mov si, word ptr StatusNames[si]	;@16A7
	call PrintStr	;@16AB
	mov dh, 13h	;@16AE
	mov dl, 1	;@16B0
	lea si, MsgWeaponColon	;@16B2
	call PrintAt	;@16B6
	mov al, byte ptr [bx+30h]	; weapon readied	;@16B9
	mov ah, 0	;@16BC
	shl ax, 1	;@16BE
	mov si, ax	;@16C0
	mov si, word ptr WeaponNames[si]	;@16C2
	call PrintStr	;@16C6
	mov dh, 14h	;@16C9
	mov dl, 1	;@16CB
	lea si, MsgArmourColon	;@16CD
	call PrintAt	;@16D1
	mov al, byte ptr [bx+28h]	; armour worn	;@16D4
	mov ah, 0	;@16D7
	shl ax, 1	;@16D9
	mov si, ax	;@16DB
	mov si, word ptr ArmourNames[si]	;@16DD
	call PrintStr	;@16E1
	mov dh, 0Dh	;@16E4
	mov dl, 1Bh	;@16E6
	lea si, MsgStrengthColon	;@16E8
	call PrintAt	;@16EC
	mov al, byte ptr [bx+12h]	; strength	;@16EF
	call PrintBcdByte	;@16F2
	mov dh, 0Eh	;@16F5
	mov dl, 1Ah	;@16F7
	lea si, MsgDexterityColon	;@16F9
	call PrintAt	;@16FD
	mov al, byte ptr [bx+13h]	; dexterity	;@1700
	call PrintBcdByte	;@1703
	mov dh, 0Fh	;@1706
	mov dl, 17h	;@1708
	lea si, MsgIntelligenceColon	;@170A
	call PrintAt	;@170E
	mov al, byte ptr [bx+14h]	; intelligence	;@1711
	call PrintBcdByte	;@1714
	mov dh, 10h	;@1717
	mov dl, 1Dh	;@1719
	lea si, MsgWisdomColon	;@171B
	call PrintAt	;@171F
	mov al, byte ptr [bx+15h]	; wisdom	;@1722
	call PrintBcdByte	;@1725
	mov dh, 12h	;@1728
	mov dl, 17h	;@172A
	lea si, MsgHitPointsColon	;@172C
	call PrintAt	;@1730
	mov ax, word ptr [bx+1Ah]	; hit points	;@1733
	call PrintBcdWord	;@1736
	mov dh, 13h	;@1739
	mov dl, 17h	;@173B
	lea si, MsgExperienceColon	;@173D
	call PrintAt	;@1741
	mov ax, word ptr [bx+1Eh]	; experience	;@1744
	call PrintBcdWord	;@1747
	mov dh, 14h	;@174A
	mov dl, 1Dh	;@174C
	lea si, MsgFoodColon	;@174E
	call PrintAt	;@1752
	mov ax, word ptr [bx+21h]	; food	;@1755
	call PrintBcdWord	;@1758
	mov dh, 15h	;@175B
	mov dl, 1Dh	;@175D
	lea si, MsgGoldColon	;@175F
	call PrintAt	;@1763
	mov ax, word ptr [bx+23h]	; gold	;@1766
	call PrintBcdWord	;@1769
LookAtChar_Done:	call WaitSpace	;@176C
	pop es	;@176F
	pop di	;@1770
	pop si	;@1771
	pop dx	;@1772
	pop cx	;@1773
	pop bx	;@1774
	pop ax	;@1775
	popf	;@1776
	ret	;@1777
LookAtChar_BadNum:	mov dh, 15h	;@1778
	mov dl, 0Eh	;@177A
	lea si, MsgOnly1To20	;@177C
	call PrintAt	;@1780
	jmp LookAtChar_Done	;@1783
LookAtChar_NoOne:	mov dh, 15h	;@1785
	mov dl, 0Dh	;@1787
	lea si, MsgNoOneThere	;@1789
	call PrintAt	;@178D
	jmp LookAtChar_Done	;@1790
;------------------------------------------------------------------------------
; FormParty: "Form the Party": refused with "(Party in Use)" while a party exists. Asks up to
; four roster numbers ("Player-1" ... "Player-4"); 0 ends the list early. A number above
; 20, an empty slot ("(No one there)") or one already chosen ("Already Selected") cancels
; everything chosen so far (ReleaseParty). Then the party is set up on foot (tile 3Fh) on
; Sosaria (location 0) at x 2Ch, y 14h, the members' records copied in, and PARTY.ULT and
; ROSTER.ULT saved: "(Formed)".
; Note: the "(No Active Players)" test (AnyAlive) runs before the records are copied, on the
; old party records (zero after a Disperse), and refuses when one of them is alive: looks
; reversed or misplaced; a party of dead characters can be formed (JourneyOnward refuses it).
; Uses: AX.
;------------------------------------------------------------------------------
FormParty:	pushf	;@1792
	push bx	;@1793
	push cx	;@1794
	push dx	;@1795
	push si	;@1796
	call ClearMenu	;@1797
	mov dh, 0Dh	;@179A
	mov dl, 0Dh	;@179C
	lea si, MsgFormTitle	;@179E
	call PrintAt	;@17A2
	mov al, byte ptr PartySize	; party size	;@17A5
	cmp al, 0	;@17A8
	je FormParty_Labels	;@17AA
	mov dh, 10h	;@17AC
	mov dl, 0Dh	;@17AE
	lea si, MsgPartyInUse	; "(Party in Use)"	;@17B0
	call PrintAt	;@17B4
	jmp FormParty_Done	;@17B7
FormParty_Labels:	mov cx, 4	; "Player-4-" ... "Player-1-" on rows 13h ... 10h	;@17BA
FormParty_LabelLoop:	mov dh, cl	;@17BD
	add dh, 0Fh	;@17BF
	mov dl, 0Fh	;@17C2
	lea si, MsgPlayerDash	;@17C4
	call PrintAt	;@17C8
	mov al, cl	;@17CB
	call PrintDigit	;@17CD
	mov al, 2Dh	; '-'	;@17D0
	call PutChar	;@17D2
	loop FormParty_LabelLoop	;@17D5
FormParty_Ask:	mov dh, byte ptr PartySize	;@17D7
	add dh, 10h	;@17DB
	mov dl, 18h	;@17DE
	call SwapCursor	;@17E0
	call AskNumber	; AskNumber: AL = BCD, AH = binary	;@17E3
	cmp ah, 14h	;@17E6
	jbe FormParty_TestEnd	;@17E9
	jmp FormParty_NoOne	;@17EB
FormParty_TestEnd:	cmp al, 0	;@17EE
	je FormParty_Finish	;@17F0
	mov bl, byte ptr PartySize	;@17F2
	mov bh, 0	;@17F6
	lea si, PartyRosterNums	;@17F8
	mov byte ptr [bx+si], ah	; the member's roster number	;@17FC
	mov bl, ah	;@17FE
	call RosterRecord	; RosterRecord	;@1800
	cmp byte ptr [bx], 0	;@1803
	jne FormParty_TestFree	;@1806
	jmp FormParty_NoOne	;@1808
FormParty_TestFree:	cmp byte ptr [bx+10h], 0FFh	; +10h: already in the party	;@180B
	jne FormParty_Take	;@180F
	jmp FormParty_Taken	;@1811
FormParty_Take:	mov byte ptr [bx+10h], 0FFh	;@1814
	inc byte ptr PartySize	;@1818
	cmp byte ptr PartySize, 4	;@181C
	jb FormParty_Ask	;@1821
FormParty_Finish:	cmp byte ptr PartySize, 0	;@1823
	je FormParty_NoOne	;@1828
	call AnyAlive	; AnyAlive, on the OLD party records	;@182A
	cmp ah, 0FFh	;@182D
	jne FormParty_Save	;@1830
	mov dh, 15h	;@1832
	mov dl, 9	;@1834
	lea si, MsgNoActivePlayers	; "(No Active Players)"	;@1836
	call PrintAt	;@183A
	call ReleaseParty	;@183D
	jmp FormParty_Done	;@1840
FormParty_Save:	mov byte ptr Location, 0	; Sosaria	;@1843
	mov byte ptr PartyBuf, 3Fh	; the party's tile: on foot	;@1848
	mov byte ptr PartyX, 2Ch	; x 44	;@184D
	mov byte ptr PartyY, 14h	; y 20	;@1852
	call RosterToParty	; RosterToParty	;@1857
	lea bx, PartyBuf	;@185A
	mov cx, 112h	;@185E
	lea dx, FilePartyUlt	;@1861
	call SaveFile	; save CX bytes at BX as the file named at DX	;@1865
	lea dx, FileRosterUlt	;@1868
	mov cx, 500h	;@186C
	lea bx, Roster	;@186F
	call SaveFile	;@1873
	mov byte ptr Location, 1	; back to 1 for the library (KeyReady)	;@1876
	mov dh, 15h	;@187B
	mov dl, 10h	;@187D
	lea si, MsgFormed	;@187F
	call PrintAt	;@1883
FormParty_Done:	call WaitSpace	;@1886
	pop si	;@1889
	pop dx	;@188A
	pop cx	;@188B
	pop bx	;@188C
	popf	;@188D
	ret	;@188E
FormParty_NoOne:	mov dh, 15h	;@188F
	mov dl, 0Dh	;@1891
	lea si, MsgNoOneThere	;@1893
	call PrintAt	;@1897
	call ReleaseParty	;@189A
	jmp FormParty_Done	;@189D
FormParty_Taken:	mov dh, 15h	;@189F
	mov dl, 0Dh	;@18A1
	lea si, MsgAlreadySelected	;@18A3
	call PrintAt	;@18A7
	call ReleaseParty	;@18AA
	jmp FormParty_Done	;@18AD
;------------------------------------------------------------------------------
; ReleaseParty: undo the party: for each member, last first, clear its roster number in
; PartyRosterNums and its roster record's party flag (+10h); the party size ends at 0.
; Uses: nothing.
;------------------------------------------------------------------------------
ReleaseParty:	pushf	;@18AF
	push ax	;@18B0
	push bx	;@18B1
	push si	;@18B2
	cmp byte ptr PartySize, 0	;@18B3
	je ReleaseParty_Done	;@18B8
ReleaseParty_Loop:	mov bl, byte ptr PartySize	;@18BA
	mov bh, 0	;@18BE
	lea si, PartyRosterNums	;@18C0
	mov al, byte ptr [bx+si-1]	;@18C4
	mov byte ptr [bx+si-1], 0	;@18C7
	mov bl, al	;@18CB
	call RosterRecord	;@18CD
	mov byte ptr [bx+10h], 0	;@18D0
	dec byte ptr PartySize	;@18D4
	jne ReleaseParty_Loop	;@18D8
ReleaseParty_Done:	pop si	;@18DA
	pop bx	;@18DB
	pop ax	;@18DC
	popf	;@18DD
	ret	;@18DE
;------------------------------------------------------------------------------
; DisperseParty: "Disperse the Party": copy the party's records back to the roster
; (PartyToRoster), release the members, clear the four party records and save PARTY.ULT
; and ROSTER.ULT: "(Dispersed!)". "(No Party)" when there is none. Uses: nothing.
;------------------------------------------------------------------------------
DisperseParty:	pushf	;@18DF
	push ax	;@18E0
	push bx	;@18E1
	push cx	;@18E2
	push dx	;@18E3
	push si	;@18E4
	push di	;@18E5
	call ClearMenu	;@18E6
	mov dh, 11h	;@18E9
	mov dl, 0Bh	;@18EB
	lea si, MsgDisperseTitle	;@18ED
	call PrintAt	;@18F1
	cmp byte ptr PartySize, 0	;@18F4
	je DisperseParty_NoParty	;@18F9
	call PartyToRoster	;@18FB
	call ReleaseParty	;@18FE
	lea di, PartyChars	;@1901
	mov cx, 100h	;@1905
	mov al, 0	;@1908
	rep stosb	;@190A
	lea bx, PartyBuf	;@190C
	mov cx, 112h	;@1910
	lea dx, FilePartyUlt	;@1913
	call SaveFile	;@1917
	lea dx, FileRosterUlt	;@191A
	mov cx, 500h	;@191E
	lea bx, Roster	;@1921
	call SaveFile	;@1925
	mov dh, 13h	;@1928
	mov dl, 0Eh	;@192A
